head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIndex;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gSchDate;
scwin.gSeq;
scwin.gChgBfafTpCd;
scwin.gDesignRsnCd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vScrenID = "ULDSTF37710.xml";
scwin.gISUR_CD;
scwin.gCOM_NM;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


//페이지 로딩 시 필요한 변수 초기화
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();


    //조회일자 오늘로 셋팅
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SchDate3.setValue(vCurDate);
    var arrCid = [{
        cid: "CPOC_DESIGN_RSN_CD",
        cnm: "cmb_CPOC_DESIGN_RSN_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=ULDSTF37710.gfm&SCREN_PROCES_TP_CD=01&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='CPOC_DESIGN_RSN_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체,";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
        objCod.CBData = strCbd;
    }
};





// 조회
scwin.fn_Search = function() {
    if ($c.stf.getObjectValue(edt_FromDate) != "") {
        // 일자 체크
        if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
            $c.win.alert("일자 올바르게 입력하십시오.");
            edt_FromDate.focus();
            return;
        }
    }
    if ($c.stf.getObjectValue(edt_ToDate) != "") {
        // 일자 체크
        if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
            $c.win.alert("일자 올바르게 입력하십시오.");
            edt_ToDate.focus();
            return;
        }
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    if ($c.stf.getObjectValue(edt_rel_FromDate) != "") {
        // 일자 체크
        if ($c.stf.getObjectValue(edt_rel_FromDate).length < 8) {
            $c.win.alert("일자 올바르게 입력하십시오.");
            edt_rel_FromDate.focus();
            return;
        }
    }
    if ($c.stf.getObjectValue(edt_rel_ToDate) != "") {
        // 일자 체크
        if ($c.stf.getObjectValue(edt_rel_ToDate).length < 8) {
            $c.win.alert("일자 올바르게 입력하십시오.");
            edt_rel_ToDate.focus();
            return;
        }
    }
    if ($c.stf.compareFromToDate2(edt_rel_FromDate, edt_rel_ToDate) == false) {
        return;
    }
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    var vFIRST_ENFORCE_FROM = $c.stf.getObjectValue(edt_FromDate);
    var vFIRST_ENFORCE_TO = $c.stf.getObjectValue(edt_ToDate);
    var vDEEMED_RELEAS_FROM = $c.stf.getObjectValue(edt_rel_FromDate);
    var vDEEMED_RELEAS_TO = $c.stf.getObjectValue(edt_rel_ToDate);
    var vENFORCE_DD = $c.stf.getObjectValue(edt_SchDate3);
    var vCPOC_DESIGN_RSN_CD = $c.stf.getObjectValue(cmb_CPOC_DESIGN_RSN_CD);
    var url;
    if (scwin.gIndex == '1') {
        url = "/ConfrmProcs.do?method=listObjCorpStatSecuTab1";
        url += "&ISUR_CD=" + vISUR_CD;
        url += "&DEP_CD=" + vDEP_CD;
        url += "&EMP_NO=" + vEMP_NO;
        url += "&FIRST_ENFORCE_FROM=" + vFIRST_ENFORCE_FROM;
        url += "&FIRST_ENFORCE_TO=" + vFIRST_ENFORCE_TO;
        url += "&DEEMED_RELEAS_FROM=" + vDEEMED_RELEAS_FROM;
        url += "&DEEMED_RELEAS_TO=" + vDEEMED_RELEAS_TO;
        url += "&CPOC_DESIGN_RSN_CD=" + vCPOC_DESIGN_RSN_CD;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Grid_Tab1.DataID = encodeURI(url);
        dts_Grid_Tab1.Reset();
        $c.cm.ShowWin(grd_Grid1);
    } else if (scwin.gIndex == '2') {
        url = "/ConfrmProcs.do?method=listObjCorpStatSecuTab2";
        url += "&ISUR_CD=" + vISUR_CD;
        url += "&ENFORCE_DD=" + vENFORCE_DD;
        url += "&DEP_CD=" + vDEP_CD;
        url += "&EMP_NO=" + vEMP_NO;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Grid_Tab2.DataID = encodeURI(url);
        dts_Grid_Tab2.Reset();
        $c.cm.ShowWin(grd_Grid2);
    }
};
scwin.dts_Grid_Tab1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid1);
};
scwin.dts_Grid_Tab1_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid_Tab1);
};
scwin.dts_Grid_Tab2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid2);
};
scwin.dts_Grid_Tab2_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid_Tab2);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    if (scwin.gIndex == '1') {
        $c.data.downloadGridViewExcel(grd_Grid1, "대상법인 현황", "", "8");
    } else if (scwin.gIndex == '2') {
        $c.data.downloadGridViewExcel(grd_Grid2, "대상법인 지정/해제 내역", "", "8");
    }
};
scwin.grd_Grid1_OnDblClick = async function(row, colid) {
    scwin.gSeq = dts_Grid_Tab1.getCellData(eval(row), "CPOC_SEQ");
    scwin.gIsurCd = dts_Grid_Tab1.getCellData(eval(row), "ISUR_CD");
    scwin.gComAbbrv = dts_Grid_Tab1.getCellData(eval(row), "COM_ABBRV");
    scwin.gChgBfafTpCd = dts_Grid_Tab1.getCellData(eval(row), "CPOC_CHG_BFAF_TP_CD");
    scwin.gDesignRsnCd = dts_Grid_Tab1.getCellData(eval(row), "CPOC_DESIGN_RSN_CD");
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "DESIGN_RELEAS_BAS_DD") {
        if (scwin.gDesignRsnCd == "4" || scwin.gDesignRsnCd == "5" || scwin.gDesignRsnCd == "6") {
            await $c.frame.CreateDialogFrame("wndDiscls", "/dsclmgt/ULDSTF37711.gfm", "지정사유별 관리", 300, 220, 610, 280, "window");
        } else if (scwin.gDesignRsnCd == "2") {
            await $c.frame.CreateDialogFrame("wndDiscls", "/dsclmgt/ULDSTF35106.gfm", "불성실공시법인(유)_STF35106", 200, 120, 1300, 800, "window");
        } else if (scwin.gDesignRsnCd == "3") {
            await $c.frame.CreateDialogFrame("STF37704", "/dsclmgt/ULDSTF37704.gfm?ISUR_CD=" + scwin.gIsurCd + "&COM_NM=" + scwin.gComAbbrv, "관리종목지정(유)", 200, 100, 850, 530, "window");
        }
    } else if (colid == "CPOC_DESIGN_RSN_DSC") {
        await $c.frame.CreateDialogFrame("wndDiscls", "/dsclmgt/ULDSTF37711.gfm", "지정사유별 관리", 300, 220, 610, 280, "window");
    }
};
scwin.grd_Grid2_OnDblClick = function(row, colid) {
    scwin.gIsurCd = dts_Grid_Tab2.getCellData(eval(row), "ISUR_CD");
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    scwin.gIndex = nIndex;
    if (scwin.gIndex == '2') {
        $c.stf.showObj(label_1, false);
        $c.stf.showObj(edt_FromDate, false);
        $c.stf.showObj(img_FromCal, false);
        $c.stf.showObj(label_5, false);
        $c.stf.showObj(edt_ToDate, false);
        $c.stf.showObj(img_ToCal, false);
        $c.stf.showObj(cmb_PeriodTp, false);
        $c.stf.showObj(label_2, false);
        $c.stf.showObj(edt_rel_FromDate, false);
        $c.stf.showObj(img_rel_FromCal, false);
        $c.stf.showObj(label_7, false);
        $c.stf.showObj(edt_rel_ToDate, false);
        $c.stf.showObj(img_rel_ToCal, false);
        $c.stf.showObj(cmb_rel_PeriodTp, false);
        $c.stf.showObj(label_8, false);
        $c.stf.showObj(cmb_CPOC_DESIGN_RSN_CD, false);
        $c.stf.showObj(label_3, true);
        $c.stf.showObj(edt_SchDate3, true);
        $c.stf.showObj(img_FromCal3, true);
    } else {
        $c.stf.showObj(label_3, false);
        $c.stf.showObj(edt_SchDate3, false);
        $c.stf.showObj(img_FromCal3, false);
        $c.stf.showObj(label_1, true);
        $c.stf.showObj(edt_FromDate, true);
        $c.stf.showObj(img_FromCal, true);
        $c.stf.showObj(label_5, true);
        $c.stf.showObj(edt_ToDate, true);
        $c.stf.showObj(img_ToCal, true);
        $c.stf.showObj(cmb_PeriodTp, true);
        $c.stf.showObj(label_2, true);
        $c.stf.showObj(edt_rel_FromDate, true);
        $c.stf.showObj(img_rel_FromCal, true);
        $c.stf.showObj(label_7, true);
        $c.stf.showObj(edt_rel_ToDate, true);
        $c.stf.showObj(img_rel_ToCal, true);
        $c.stf.showObj(cmb_rel_PeriodTp, true);
        $c.stf.showObj(label_8, true);
        $c.stf.showObj(cmb_CPOC_DESIGN_RSN_CD, true);
    }
    scwin.fn_Search();
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.img_rel_FromCal_onclick = function() {
    popUpCalendar2(edt_rel_FromDate);
};
scwin.img_rel_ToCal_onclick = function() {
    popUpCalendar2(edt_rel_ToDate);
};
scwin.img_FromCal3_onclick = function() {
    popUpCalendar2(edt_SchDate3);
};
scwin.cmb_rel_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_rel_PeriodTp, "VALUE", cmb_rel_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_rel_FromDate, edt_rel_ToDate);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.gform_onload = function() {
    scwin.fn_SetCode();
    $c.cm.PanelToGroupBox(panel_5);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    MxTab_1.setSelectedTabIndex("1");
    cmb_CPOC_DESIGN_RSN_CD.BindColVal = "";
};
